// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.diimport com.roshan.persona.brain.stream.TtsBridgeimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.launchimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Voice TTS Bridge. * * Implements Brain's [TtsBridge] interface by delegating to Voice's * [EmotionalTtsEngine]. Tokens are buffered until a sentence boundary * is detected (`.`, `!`, `?`, newline), then spoken as a complete sentence. * * Strategy §5.4: "TTS is wired in Module 5 (Voice). The StreamCoordinator * calls TtsBridge.speak(token) for each generated token. The TTS engine * should buffer tokens internally and speak them in order." * * ## Barge-In * * When [stop] is called (barge-in), the current sentence buffer is cleared * and EmotionalTtsEngine.stopForBargeIn() is called to immediately stop * any in-progress speech. * * @see <a href="docs/strategy/NOUS-Module-Strategy-2-14-extracted.txt">§5.4 Text-to-Speech</a> */@Singletonclass VoiceTtsBridge @Inject constructor(    private val emotionalTtsEngine: EmotionalTtsEngine,) : TtsBridge {    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())    private val bufferMutex = Mutex()    private val tokenBuffer = StringBuilder()    override suspend fun speak(token: String) {        bufferMutex.withLock {            tokenBuffer.append(token)            // Check for sentence boundary.            val text = tokenBuffer.toString()            val lastChar = text.lastOrNull()            if (lastChar == '.' || lastChar == '!' || lastChar == '?' || lastChar == '\n') {                val sentence = tokenBuffer.toString().trim()                tokenBuffer.clear()                if (sentence.isNotEmpty()) {                    scope.launch {                        try {                            emotionalTtsEngine.speak(                                text = sentence,                                emotion = Emotion.NEUTRAL,                                persona = VoicePersona.ATLAS,  // Default persona — overridden by VoiceFacade                            )                        } catch (e: Exception) {                            Timber.e(e, "TTS speak failed for sentence: ${sentence.take(50)}...")                        }                    }                }            }        }    }    override fun stop() {        scope.launch {            bufferMutex.withLock {                tokenBuffer.clear()            }            emotionalTtsEngine.stopForBargeIn()        }    }}